const item = $input.first();
const envelope = item.json || {};
const headers = envelope.headers || {};
const body = envelope.body || envelope;
const expected = String($env.N8N_WEBHOOK_SECRET || '');
const received = String(headers['x-webhook-token'] || headers['X-Webhook-Token'] || '');
if (!expected || received !== expected) throw new Error('Unauthorized webhook token');

const required = ['cardId', 'idempotencyKey', 'pageId', 'accessToken', 'callbackUrl'];
for (const field of required) {
  if (!String(body[field] || '').trim()) throw new Error(`Missing required field: ${field}`);
}
if (!/^https:\/\//i.test(String(body.callbackUrl))) throw new Error('callbackUrl must use HTTPS');

const mediaType = ['none', 'image', 'video'].includes(body.mediaType) ? body.mediaType : 'none';
if (mediaType !== 'none' && !/^https:\/\//i.test(String(body.mediaUrl || ''))) throw new Error('mediaUrl must use HTTPS');

const store = $getWorkflowStaticData('global');
store.deliveries = store.deliveries || {};
const now = Date.now();
for (const [key, value] of Object.entries(store.deliveries)) {
  if (!value?.updatedAt || now - value.updatedAt > 30 * 24 * 60 * 60 * 1000) delete store.deliveries[key];
}
const key = String(body.idempotencyKey);
const existing = store.deliveries[key];
const locked = existing && (existing.status === 'published' || (existing.status === 'processing' && now - existing.updatedAt < 20 * 60 * 1000));
if (locked) {
  return [{ json: { duplicate: true, idempotencyKey: key, cached: existing, cardId: body.cardId } }];
}
store.deliveries[key] = { status: 'processing', cardId: body.cardId, updatedAt: now };

let apiUrl;
let facebookBody;
if (mediaType === 'video') {
  apiUrl = `https://graph.facebook.com/v19.0/${body.pageId}/videos`;
  facebookBody = { description: String(body.content || ''), file_url: String(body.mediaUrl), access_token: String(body.accessToken), published: true };
} else if (mediaType === 'image') {
  apiUrl = `https://graph.facebook.com/v19.0/${body.pageId}/photos`;
  facebookBody = { caption: String(body.content || ''), url: String(body.mediaUrl), access_token: String(body.accessToken), published: true };
} else {
  apiUrl = `https://graph.facebook.com/v19.0/${body.pageId}/feed`;
  facebookBody = { message: String(body.content || ''), access_token: String(body.accessToken) };
}
return [{ json: { duplicate: false, prepared: { cardId: String(body.cardId), idempotencyKey: key, callbackUrl: String(body.callbackUrl), mediaType, apiUrl, facebookBody } } }];

const response = $input.first().json || {};
const prepared = $items('Validate, Lock & Prepare', 0, 0)[0].json.prepared;
const postId = String(response.id || response.post_id || '');
const store = $getWorkflowStaticData('global');
store.deliveries = store.deliveries || {};
store.deliveries[prepared.idempotencyKey] = { status: 'published', cardId: prepared.cardId, postId, postUrl: '', updatedAt: Date.now() };
return [{ json: { prepared, postId, postUrl: '' } }];

const response = $input.first().json || {};
const prepared = $items('Validate, Lock & Prepare', 0, 0)[0].json.prepared;
const message = String(response.error?.message || response.error?.type || response.message || JSON.stringify(response));
const store = $getWorkflowStaticData('global');
if (store.deliveries) delete store.deliveries[prepared.idempotencyKey];
return [{ json: { prepared, error: message.slice(0, 1000) } }];
